import {writeFile} from 'node:fs/promises';
import {dashboardApp} from '../src/dashboard-app.mjs';
// Freeze browser code before Wrangler transforms server-side function declarations.
await writeFile(new URL('../src/dashboard-script.mjs',import.meta.url),
 '// Generated by scripts/build-dashboard.mjs. Edit dashboard-app.mjs instead.\nexport const dashboardScript = '+JSON.stringify(dashboardApp.toString())+';\n');
console.log('Prepared self-contained browser script before Worker bundling.');
